using System.Drawing;using System.Windows.Forms;namespace ServiceTool{internal sealed class InheritedThemeLabel:Label{protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(BackColor);var flags=TextFormatFlags.NoPrefix|TextFormatFlags.WordBreak;if(TextAlign==ContentAlignment.MiddleCenter)flags|=TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter;else if(TextAlign==ContentAlignment.MiddleLeft)flags|=TextFormatFlags.VerticalCenter;if(AutoEllipsis)flags|=TextFormatFlags.EndEllipsis;TextRenderer.DrawText(e.Graphics,Text,Font,ClientRectangle,ForeColor,flags);}}}